const prev = $('Parse AI Result').item.json;
const { session_id, action, started_at, health, log_summary, ai_analysis, logs } = prev;
const finished_at = new Date().toISOString();
const COLORS = { CRITICAL:'#A32D2D', HIGH:'#C5610A', MEDIUM:'#185FA5', LOW:'#3B6D11', NONE:'#4A4A40' };

const pods = (logs || []).filter(l => l.pod).map(l => ({
  name: l.pod,
  status: l.severity === 'NONE' ? 'Running' : 'ThreatDetected',
  ip: ''
})) || [];

const formattedLogs = (logs || []).map(l => ({
  pod_name: l.pod,
  log_entry: l.log_preview || ''
})) || [];

return [{ json: {
  success: true,
  action,
  session_id,
  timing: {
    started_at,
    finished_at,
    duration_ms: new Date(finished_at) - new Date(started_at)
  },
  pods: pods,
  logs: formattedLogs,
  ai_analysis: {
    threat_level: ai_analysis.threat_level,
    attack_types: ai_analysis.attack_types,
    affected_services: ai_analysis.affected_services,
    summary: ai_analysis.summary,
    confidence_score: ai_analysis.confidence_score,
    recommendations: ai_analysis.recommendations,
    requires_immediate_action: ai_analysis.requires_immediate_action,
    cluster_health_score: ai_analysis.cluster_health_score,
    threat_details: ai_analysis.threat_details
  },
  log_summary: log_summary || {},
  threats: (logs || []).filter(l => l.hasThreat).map(l => ({
    pod: l.pod,
    severity: l.severity,
    detections: l.detections
  }))
}}];

const i = $input.first().json;
const a = i.ai_analysis || {};
const toArray = (val) => Array.isArray(val) ? val : (typeof val === 'string' ? [val] : []);
return [{ json: {
  session_id:        i.session_id,
  threat_level:      a.threat_level,
  attack_types:      toArray(a.attack_types),
  affected_services: toArray(a.affected_services),
  summary:           a.summary,
  recommendations:   toArray(a.recommendations),
  confidence:        a.confidence_score,
  raw_response:      i.raw_ai_text || '',
  logs_analyzed:     i.log_summary.total_log_lines || 0,
  threat_detected:   (a.threat_level !== 'NONE')
}}];

const llmOut = $input.first().json;
const prev   = $('Detect + Build Prompt').item.json;

if (prev.is_stop) {
  return [{ json: { ...prev, ai_analysis: {
    threat_level:'NONE', attack_types:[], affected_services:[],
    summary:'Monitoring stopped.', threat_details:'',
    recommendations:[], confidence_score:1.0,
    cluster_health_score:1.0, requires_immediate_action:false
  }, raw_ai_text:'' }}];
}

// Handle no threats case
if (prev.ollama_prompt === '__SKIP__') {
  return [{ json: { ...prev, ai_analysis: {
    threat_level:'NONE', attack_types:[], affected_services:[],
    summary:'No threats detected in CIMS pod logs.', threat_details:'',
    recommendations:['Continue monitoring'], confidence_score:1.0,
    cluster_health_score: prev.health.totalPods > 0 ? parseFloat((prev.health.runningPods/prev.health.totalPods).toFixed(2)) : 0.5,
    requires_immediate_action:false
  }, raw_ai_text:'No threats found' }}];
}

const rawText = llmOut.text || llmOut.output || llmOut.response || '';
let ai_analysis;
try {
  const cleaned = rawText.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
  const match   = cleaned.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON in AI output');
  ai_analysis = JSON.parse(match[0]);
  ai_analysis.confidence_score     = Math.min(1,Math.max(0,Number(ai_analysis.confidence_score)||0));
  ai_analysis.cluster_health_score = Math.min(1,Math.max(0,Number(ai_analysis.cluster_health_score)||0));
} catch(err) {
  const ls = prev.log_summary||{};
  const h  = prev.health||{};
  ai_analysis = {
    threat_level: ls.max_severity||'UNKNOWN',
    attack_types: ls.attack_types||[],
    affected_services: (prev.logs||[]).filter(l=>l.hasThreat).map(l=>l.pod),
    summary: `AI parse error: ${err.message.slice(0,80)}. Rule scan: ${(ls.attack_types||[]).join(', ')||'nothing found'}.`,
    threat_details: `Fallback. Raw: ${rawText.slice(0,200)}`,
    recommendations: ['Check Ollama','Re-run scan','Review logs manually'],
    confidence_score: 0.35,
    cluster_health_score: h.totalPods>0 ? parseFloat((h.runningPods/h.totalPods).toFixed(2)) : 0.5,
    requires_immediate_action: (ls.max_severity==='CRITICAL'||ls.max_severity==='HIGH')
  };
}

return [{ json: { ...prev, ai_analysis, raw_ai_text: rawText.slice(0,800) }}];

// ── Pull data from watcher ───────────────────────
const parseOut = $input.first().json;
const { action, session_id, namespace, source, started_at, is_stop,
        auditEvents, summary, total_pods, pods_with_threats, 
        total_threats, max_severity } = parseOut;

// ── Stop short-circuit ─────────────────────────────
if (is_stop) {
  return [{ json: {
    ...parseOut,
    logs: [], log_summary: { max_severity:'NONE', attack_types:[], pods_with_threats:0, total_log_lines:0 },
    health: { totalPods:0, runningPods:0, failedPods:0, pendingPods:0, warnings:0 },
    ollama_prompt: '__SKIP__'
  }}];
}

// ── Process watcher events ──────────────────────
const logs = (auditEvents || []).map(e => ({
  pod: e.pod,
  service: e.service,
  severity: e.max_severity,
  hasThreat: e.has_threat,
  detections: e.detections || [],
  log_preview: e.log_preview || ''
}));

const log_summary = {
  max_severity: max_severity || 'NONE',
  attack_types: [...new Set((auditEvents || []).flatMap(e => 
    (e.detections || []).map(d => d.pattern)
  ))],
  pods_with_threats: pods_with_threats || 0,
  total_log_lines: (auditEvents || []).reduce((s, e) => s + (e.log_lines || 0), 0),
  total_errors: (auditEvents || []).filter(e => 
    e.detections?.some(d => d.severity === 'MEDIUM' || d.severity === 'HIGH' || d.severity === 'CRITICAL')
  ).length
};

const health = {
  totalPods: total_pods || 0,
  runningPods: (auditEvents || []).filter(e => e.status === 'Running').length,
  failedPods: (auditEvents || []).filter(e => e.status === 'Failed').length,
  pendingPods: (auditEvents || []).filter(e => e.status === 'Pending').length,
  warnings: (auditEvents || []).filter(e => e.status === 'Error').length,
  highRestartPods: []
};

// ── Build Ollama prompt ─────────────────────────
const ollama_prompt = log_summary.attack_types.length > 0 
  ? `You are a cybersecurity expert analyzing K8s pod logs from CIMS healthcare app. 

Analyze these log events for attack indicators:
- SQL injection, XSS, command injection, auth bypass
- Privilege escalation, secret/configmap access
- Data exfiltration, reconnaissance
- Anomalous behavior: unusual users, off-hours activity

Events:
${JSON.stringify(auditEvents, null, 2).slice(0, 3000)}

Respond ONLY with valid JSON:
{
  "threat_level": "CRITICAL|HIGH|MEDIUM|LOW|NONE",
  "attack_types": ["array of detected types"],
  "summary": "brief explanation",
  "threat_details": "specific details",
  "recommendations": ["action 1", "action 2"],
  "confidence_score": 0.0-1.0,
  "requires_immediate_action": true|false
}`
  : '__SKIP__';

return [{ json: {
  ...parseOut, logs, log_summary, health, ollama_prompt
}}];

// ── Read webhook metadata ─────────────────────────
const webhookItem = $('Webhook').first().json;
const body = webhookItem.body || webhookItem || {};
const action = body.action || 'analyze';
const session_id = body.session_id || ('cims_' + Date.now());
const namespace = body.namespace || 'cims';
const source = body.source || 'platform-voc-ui';
const started_at = body.timestamp || new Date().toISOString();
const is_stop = action === 'stop';

// ── Collect cims logs from ES node output ──────
const items = $input.all();
const esDocs = [];
for (const item of items) {
  const doc = item.json;
  if (doc && doc.kubernetes && doc.kubernetes.namespace === 'cims') {
    esDocs.push(doc);
  }
}

// ── Detection patterns (best-effort signatures) ──
const PATTERNS = [
  { type: 'SQL_INJECTION', severity: 'CRITICAL',
    pattern: new RegExp('\\bselect\\b|\\bunion\\b|insert\\s+into|drop\\s+table|alter\\s+table|create\\s+table|delete\\s+from|or\\s+[0-9]+\\s*=\\s*[0-9]+|sleep\\s*\\(|waitfor\\s+delay|benchmark\\s*\\(|--\\s', 'i') },
  { type: 'XSS', severity: 'HIGH',
    pattern: new RegExp('<\\s*script|</\\s*script|javascript\\s*:|onerror\\s*=|onload\\s*=|document\\.cookie|alert\\s*\\(|eval\\s*\\(|innerHTML|%3Cscript%3E|%3C/script%3E', 'i') },
  { type: 'PATH_TRAVERSAL', severity: 'HIGH',
    pattern: new RegExp('\\.\\.\\/|\\.\\.\\\\|%2e%2e%2f|%2e%2e%5c|\\/etc\\/passwd|\\/etc\\/shadow|%2fetc%2fpasswd|\\/proc\\/self', 'i') },
  { type: 'COMMAND_INJECTION', severity: 'CRITICAL',
    pattern: new RegExp(';\\s*(cat|ls|id|whoami|curl|wget|nc|bash|sh|python|perl|ruby|php|node)\\s|\\|\\s*(cat|ls|id|whoami|curl|wget|nc|bash|sh)\\s|\\$\\(|`[^`]+`', 'i') },
  { type: 'AUTH_BYPASS', severity: 'HIGH',
    pattern: new RegExp('admin\\s*[:#].{0,4}admin|password.{0,6}admin|bypass.{0,15}auth|Authorization.{0,10}Bearer.{0,10}(test|null|undefined)', 'i') }
];

// ── Scan each log line ────────────────────────
const threats = [];
const podSet = new Set();
for (const doc of esDocs) {
  const message = doc.message || '';
  const kube = doc.kubernetes || {};
  const pod = (kube.pod && kube.pod.name) || '';
  const service = (kube.deployment && kube.deployment.name) || (kube.container && kube.container.name) || '';
  const logPath = (doc.log && doc.log.file && doc.log.file.path) || '';
  if (pod) podSet.add(pod);
  for (const p of PATTERNS) {
    if (p.pattern.test(message)) {
      threats.push({
        pod, service,
        severity: p.severity,
        pattern: p.type,
        message: message.substring(0, 500),
        logPath,
        timestamp: doc['@timestamp'] || ''
      });
    }
  }
}

// ── Build auditEvents (group per pod) ────────
const byPod = {};
for (const t of threats) {
  const key = t.pod || t.service || 'unknown';
  if (!byPod[key]) byPod[key] = { pod: t.pod, service: t.service, detections: [], log_lines: 0, status: 'Failed' };
  const dedupeKey = t.pattern + '|' + t.message.substring(0, 120);
  if (!byPod[key].detections.some(d => d.pattern === t.pattern && d.message === t.message)) {
    byPod[key].detections.push({ pattern: t.pattern, severity: t.severity, message: t.message, logPath: t.logPath, timestamp: t.timestamp });
    byPod[key].log_lines++;
  }
}

const healthyPodCount = podSet.size;
const podsWithThreats = Object.keys(byPod).length;

// Healthy pods (no threat) get status Running
const auditEvents = [];
for (const pod of podSet) {
  if (byPod[pod]) {
    auditEvents.push({
      ...byPod[pod],
      has_threat: true,
      max_severity: byPod[pod].detections.reduce((max, d) => {
        const order = { 'LOW':1, 'MEDIUM':2, 'HIGH':3, 'CRITICAL':4 };
        return (order[d.severity]||0) > (order[max]||0) ? d.severity : max;
      }, 'LOW'),
      log_preview: (byPod[pod].detections[0] && byPod[pod].detections[0].message) || ''
    });
  } else {
    auditEvents.push({ pod, service: '', detections: [], has_threat: false, max_severity: 'NONE', status: 'Running', log_preview: '', log_lines: 0 });
  }
}

const severityOrder = { 'NONE':0, 'LOW':1, 'MEDIUM':2, 'HIGH':3, 'CRITICAL':4 };
let max_severity = 'NONE';
for (const e of auditEvents) {
  if (severityOrder[e.max_severity] > severityOrder[max_severity]) max_severity = e.max_severity;
}

return [{
  json: {
    action, session_id, namespace, source, started_at, is_stop,
    auditEvents,
    summary: threats.length > 0
      ? 'Detected ' + threats.length + ' potential attack ' + (threats.length===1?'signal':'signals') + ' in CIMS pod logs.'
      : 'No attack indicators found in CIMS pod logs.',
    total_pods: healthyPodCount,
    pods_with_threats: podsWithThreats,
    total_threats: threats.length,
    max_severity,
    es_docs_scanned: esDocs.length
  }
}];
